type DisposeHandler = () => void;

type ChangeCallback<T = any> = (data?: T) => void;

type ContextEvent = {
    type: string;
    payload?: any;
};

enum ContextEvents {
    CONTEXT_CHANGE = "epi:context:change",
    CONTEXT_REFRESH = "epi:context:refresh",
}

function subscribe<T>(eventName: ContextEvents, type: string, callback: ChangeCallback<T>): DisposeHandler {
    if (!type) {
        return () => {};
    }

    const handler = (event: Event) => {
        const data: ContextEvent = (event as CustomEvent)?.detail;

        if (data && data.type === type) {
            callback(data.payload);
        }
    };

    window.addEventListener(eventName, handler);

    return () => {
        window.removeEventListener(eventName, handler);
    };
}

function publish<T>(eventName: ContextEvents, type: string, data?: T): void {
    if (!type) {
        return;
    }

    const event = new CustomEvent(eventName, { detail: { type, payload: data } });
    window.dispatchEvent(event);
}

export const ContextEventManager = {
    change: <T>(type: string, data?: T) => publish<T>(ContextEvents.CONTEXT_CHANGE, type, data),
    onChange: <T>(type: string, callback: ChangeCallback<T>) =>
        subscribe<T>(ContextEvents.CONTEXT_CHANGE, type, callback),

    refresh: (type: string) => publish(ContextEvents.CONTEXT_REFRESH, type),
    onRefresh: <T>(type: string, callback: ChangeCallback<T>) =>
        subscribe<T>(ContextEvents.CONTEXT_REFRESH, type, callback),
};
